package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="shared_settlements") @Data @NoArgsConstructor @AllArgsConstructor @Builder
public class SharedSettlement { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="group_id",nullable=false) private SharedExpenseGroup group; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="paid_by_member_id",nullable=false) private SharedGroupMember paidBy; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="paid_to_member_id",nullable=false) private SharedGroupMember paidTo; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(nullable=false) private LocalDate settlementDate; private String paymentMode; private String notes; @Builder.Default @Column(nullable=false) private Boolean reversed=false; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by",nullable=false) private User createdBy; @Builder.Default @Column(nullable=false,updatable=false) private LocalDateTime createdAt=LocalDateTime.now(); }
